const VALUES = [
  ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
  ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
  ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1]
];

const NUMERAL_TO_VALUE = Object.fromEntries(VALUES);
const VALID_NUMERALS = new Set(Object.keys(NUMERAL_TO_VALUE));

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Value must be an integer between 1 and 3999');
  }

  let result = '';
  let remaining = n;
  for (const [numeral, value] of VALUES) {
    while (remaining >= value) {
      result += numeral;
      remaining -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('Invalid Roman numeral');
  }

  // Check for invalid characters
  for (const ch of s) {
    if (!VALID_NUMERALS.has(ch)) {
      throw new Error('Invalid Roman numeral');
    }
  }

  // Check structural validity using a regex
  // This pattern validates standard subtractive notation for 1..3999
  const validRoman = /^(M{0,3})(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
  if (!validRoman.test(s)) {
    throw new Error('Invalid Roman numeral');
  }

  let total = 0;
  let i = 0;
  while (i < s.length) {
    const twoChar = s.slice(i, i + 2);
    if (twoChar in NUMERAL_TO_VALUE && twoChar.length === 2) {
      total += NUMERAL_TO_VALUE[twoChar];
      i += 2;
    } else {
      total += NUMERAL_TO_VALUE[s[i]];
      i += 1;
    }
  }

  return total;
}

